    up_body(Delim, Rest, Codes),
    atom_codes(Value, Codes).
up_body(Delim, [Delim], []) :- !.
up_body(Delim, [Delim, Delim|Rest], [Delim|Out]) :- !, up_body(Delim, Rest, Out).
